  /** Time-sliced: sort trees in range into the active list and the static impostor batches. */
  private *rebuild(focus: Vector3, px: number): Generator<void> {
    for (const b of this.statics.values()) b.sCount = 0;
    this.nextActive.length = 0;
    const scatter = this.world.scatter;
    const cs = scatter.chunkSize;
    const maxD = this.opts.maxDistance;
    const move = (this.opts.rebuildDistance ?? 5) + 4;
    const bounds = this.world.map.bounds;
    const x0 = Math.floor(Math.max(bounds.minX - 300, focus.x - maxD) / cs);
    const x1 = Math.floor(Math.min(bounds.maxX + 300, focus.x + maxD) / cs);
    const z0 = Math.floor(Math.max(bounds.minZ - 300, focus.z - maxD) / cs);
    const z1 = Math.floor(Math.min(bounds.maxZ + 300, focus.z + maxD) / cs);
    for (let cz = z0; cz <= z1; cz++)
      for (let cx = x0; cx <= x1; cx++) {
        if (Math.hypot((cx + 0.5) * cs - focus.x, (cz + 0.5) * cs - focus.z) - cs * 0.71 > maxD) continue;
        for (const inst of scatter.chunk(cx, cz).instances) {
          if (!inst.tree) continue;
          const st = this.stateOf(inst);
          if (!st) continue;
          const dx = st.cx - focus.x;
          const dy = st.cy - focus.y;
          const dz = st.cz - focus.z;
          const dist = Math.sqrt(dx * dx + dy * dy + dz * dz);
          if (dist > maxD) continue;
          const { t, hysteresis: margin } = this.budget(st.lv);
          // Largest projected height before the next job: below the LOD2 threshold it stays an impostor.
          const hMax = (st.diameter * px * ZOOM_MARGIN) / Math.max(dist - move, 0.5);
          // Not drawn last frame (new, or a static impostor): it is settled (an impostor here), never mid-fade.
          const fresh = st.seen < this.frame - 1;
          if (fresh) {
            st.from = st.to = 3;
            st.fade = 1;
          }
          st.seen = this.frame;
          if (hMax * (1 + margin) < t[2] && st.from === 3 && st.to === 3) {
            this.stageStatic(st, Math.atan2(dz, dx));
          } else this.nextActive.push(st);
        }
        yield;
      }
    this.focusX = focus.x;
    this.focusZ = focus.z;
    [this.active, this.nextActive] = [this.nextActive, this.active];
    for (const b of this.statics.values()) {
      [b.cMat, b.sMat] = [b.sMat, b.cMat];
      [b.cInst, b.sInst] = [b.sInst, b.cInst];
      [b.cAngle, b.sAngle] = [b.sAngle, b.cAngle];
      b.cCount = b.sCount;
      this.packStatic(b);
    }
    this.packedView = this.view && { ...this.view };
    this.commits++;
  }

  private stageStatic(st: TreeState, angle: number): void {
    const b = this.staticBatch(st.lv);
    const i = b.sCount++;
    b.sMat = grow(b.sMat, (i + 1) * 16);
    b.sInst = grow(b.sInst, (i + 1) * 4);
    b.sAngle = grow(b.sAngle, i + 1);
    b.sMat.set(st.m, i * 16);
    b.sInst.set(st.inst, i * 4);
    b.sAngle[i] = angle;
  }

  /** Every frame: select, fade and write every active tree into the dynamic batches. */
  private drawActive(px: number, dt: number): void {
    this.frame++;
    for (const b of this.dynamic.values()) b.count = 0;
    const v = this.view;
    const shadowD = this.opts.shadowDistance;
    const sx = this.steadyPos.x;
    const sy = this.steadyPos.y;
    const sz = this.steadyPos.z;
    let drawn = 0;
    let flickering = 0;
    for (const st of this.active) {
      const dx = st.cx - sx;
      const dy = st.cy - sy;
      const dz = st.cz - sz;
      const dist = Math.max(Math.sqrt(dx * dx + dy * dy + dz * dz), 0.5);
      const near = dist < shadowD;
      let visible = near;
      if (!visible && v) {
        let a = Math.abs(Math.atan2(st.cz - this.focusZ, st.cx - this.focusX) - v.yaw) % (2 * Math.PI);
        if (a > Math.PI) a = 2 * Math.PI - a;
        visible = a <= v.half;
      } else if (!v) visible = true;
      const lod = this.budget(st.lv);
      const h = (st.diameter * px) / dist;
      const sel = selectLevel(h, fadeTarget(st), lod.t, lod.hysteresis);
      const fresh = st.seen < this.frame - 1;
      st.seen = this.frame;
      // Culled (keeps its state) or coming into view: its selected level at once, no fade.
      const snap = !visible || !st.visible || fresh || dt === 0;
      if (stepFade(st, sel, snap, dt, lod.fadeTime)) this.changed(st);
      st.visible = visible;
      while (st.changes.length && st.changes[0] < this.time - 1) st.changes.shift();
      const flicker = st.changes.length > 2;
      if (flicker) flickering++;
      // Shadow: one level coarser than the level the tree is settled on (`from` until a fade ends).
      const sh = near ? shadowLevel(st.from) : -1;
      const debug = (lvl: number) => lvl + (st.from !== st.to ? 4 : 0) + (flicker ? 8 : 0);
      if (st.from === st.to) {
        if (visible) {
          this.emit(st, st.from, SOLID, 1, sh === st.from, debug(st.from));
          drawn++;
        }
        if (sh >= 0 && (sh !== st.from || !visible)) this.emit(st, sh, SHADOW_ONLY, 1, true, 0);
      } else {
        if (visible) {
          this.emit(st, st.from, OUTGOING, st.fade, sh === st.from, debug(st.from));
          this.emit(st, st.to, INCOMING, st.fade, sh === st.to, debug(st.to));
          drawn++;
        }
        if (sh >= 0 && ((sh !== st.from && sh !== st.to) || !visible)) this.emit(st, sh, SHADOW_ONLY, 1, true, 0);
      }
    }
    for (const b of this.dynamic.values()) this.upload(b, b.count);
    this.drawn = drawn + [...this.statics.values()].reduce((n, b) => n + b.count, 0);
    this.flickering = flickering;
  }

  private changed(st: TreeState): void {
    st.changes.push(this.time);
    if (st.changes.length > 4) st.changes.shift();
  }

  private emit(st: TreeState, level: number, role: number, fade: number, shadow: boolean, debug: number): void {
    const b = this.dynamicBatch(st.lv, level);
    const i = b.count++;
    if (b.count > b.capacity) this.ensureCapacity(b, b.count);
    b.mat.set(st.m, i * 16);
    b.inst.set(st.inst, i * 4);
    b.fade[i * 4] = fade;
    b.fade[i * 4 + 1] = role;
    b.fade[i * 4 + 2] = shadow ? 1 : 0;
    b.fade[i * 4 + 3] = debug;
  }

  private dynamicBatch(lv: LoadedVariant, level: number): Batch {
    const key = `${lv.info.species}#${lv.info.index}:${level}`;
    let b = this.dynamic.get(key);
    if (!b) {
      b = this.newBatch();
      this.createMeshes(b, lv, level, `lod${level}`);
      this.ensureCapacity(b, 64);
      this.dynamic.set(key, b);
    }
    return b;
  }

  private staticBatch(lv: LoadedVariant): StaticBatch {
    const key = `${lv.info.species}#${lv.info.index}`;
    let b = this.statics.get(key);
    if (!b) {
      const f = () => new Float32Array(0);
      b = {
        ...this.newBatch(),
        lv,
        sMat: f(),
        sInst: f(),
        sAngle: f(),
        sCount: 0,
        cMat: f(),
        cInst: f(),
        cAngle: f(),
        cCount: 0,
      };
      this.createMeshes(b, lv, 3, 'static');
      this.ensureCapacity(b, 64);
      this.statics.set(key, b);
    }
    return b;
  }

  private newBatch(): Batch {
    return {
      meshes: [],
      geometries: [],
      capacity: 0,
      count: 0,
      mat: new Float32Array(0),
      inst: new Float32Array(0),
      fade: new Float32Array(0),
      aMat: null,
      aInst: null,
      aFade: null,
    };
  }

  private setView(camera: PerspectiveCamera): void {
    const dir = camera.getWorldDirection(_dir);
    const flat = Math.hypot(dir.x, dir.z);
    const halfFov = Math.atan(Math.tan((camera.fov * Math.PI) / 360) * camera.aspect);

