rep(s[i0:i1],"""  /** While true, stamps wrap around the S x S tile (the dense patch repeats on tiled cards). */
  let wrap = false;
  const stamp = (cx: number, cy: number, r: number, v: number, x0: number) => {
    const ya = Math.floor(cy - r);
    const yb = Math.ceil(cy + r);
    const xa = Math.floor(cx - r);
    const xb = Math.ceil(cx + r);
    for (let yy = wrap ? ya : Math.max(0, ya); yy <= (wrap ? yb : Math.min(S - 1, yb)); yy++)
      for (let xx = wrap ? xa : Math.max(0, xa); xx <= (wrap ? xb : Math.min(S - 1, xb)); xx++) {
        const d = Math.sqrt((xx - cx) ** 2 + (yy - cy) ** 2);
        const a = Math.min(1, Math.max(0, r - d + 0.5));
        const x = ((xx % S) + S) % S;
        const y = ((yy % S) + S) % S;
        const k = y * W + x0 + x;
        if (a > alpha[k]) {
          alpha[k] = a;
          shade[k] = v;
        }
      }
  };
""")
i0=s.index("  const spray = (")
i1=s.index("  if (kind === 'needles') {\n    // Spray along v")
rep(s[i0:i1],"""  const blob = (ox: number, seed: number) => {
    // The dense, tileable leaf patch of the tiled cards: the same leaves / needles, at the same size in px, as the
    // cluster half, so a merged card shows the same foliage at the same texel density (trees/Lod.md#levels).
    wrap = true;
    const r = (k: number) => unit(mix32(seed, k));
    if (kind === 'needles')
      for (let i = 0; i < 16; i++) {
        const cx = r(i * 5) * S;
        const cy = r(i * 5 + 1) * S;
        const ang = r(i * 5 + 2) * Math.PI * 2;
        const len = 64 + 20 * r(i * 5 + 3);
        const dx = Math.cos(ang);
        const dy = Math.sin(ang);
        line(cx, cy, cx + dx * len, cy + dy * len, 1.2, 0.5, 0.6, ox);
        for (let n = 0; n * 4.6 < len; n++) {
          const f = (n * 4.6) / len;
          for (const side of [-1, 1]) {
            const a = ang + side * (0.85 + 0.25 * r(i * 97 + n * 2 + (side > 0 ? 1 : 0)));
            const l = 40 * (1 - f * 0.45) * 0.8;
            const px = cx + dx * len * f;
            const py = cy + dy * len * f;
            line(px, py, px + Math.cos(a) * l, py + Math.sin(a) * l, 0.75, 0.6, 1.08, ox);
          }
        }
      }
    else
      for (let i = 0; i < 110; i++) {
        const cx = r(i * 5) * S;
        const cy = r(i * 5 + 1) * S;
        const ang = r(i * 5 + 2) * Math.PI * 2;
        if (i % 6 === 0) line(cx, cy, cx + Math.cos(ang) * 30, cy + Math.sin(ang) * 30, 0.8, 0.5, 0.55, ox);
        leaf(cx, cy, ang, 20 + 8 * r(i * 5 + 3), 6.5, 0.75 + 0.35 * r(i * 5 + 4), ox);
      }
    wrap = false;
  };
""")
open(p,'w').write(s)
