        if (Math.hypot((cx + 0.5) * cs - focus.x, (cz + 0.5) * cs - focus.z) - cs * 0.71 > maxD) continue;
        for (const inst of scatter.chunk(cx, cz).instances) {
          if (!inst.tree) continue;
          const st = this.stateOf(inst);
          if (!st) continue;
          const dx = st.cx - focus.x;
          const dy = st.cy - focus.y;
          const dz = st.cz - focus.z;
          const dist = Math.sqrt(dx * dx + dy * dy + dz * dz);
          if (dist > maxD) continue;
          const { t, hysteresis: margin } = this.budget(st.lv);
          // Neither drawn last frame nor in the last static batches: new, it takes its level at once.
          if (st.seen < this.frame - 1 && st.staticJob !== this.committedJob) {
