      [b.cInst, b.sInst] = [b.sInst, b.cInst];
      [b.cFade, b.sFade] = [b.sFade, b.cFade];
      [b.cAngle, b.sAngle] = [b.sAngle, b.cAngle];
      [b.cAlways, b.sAlways] = [b.sAlways, b.cAlways];
      b.cCount = b.sCount;
