  if (step.startsWith('wait:')) { await sleep(Number(step.slice(5))); continue; }
  if (step === 'shot') { const r = await send('Page.captureScreenshot', { format: 'png' }); writeFileSync(`${out}-${n++}.png`, Buffer.from(r.result.data, 'base64')); continue; }
  const r = await send('Runtime.evaluate', { expression: step, awaitPromise: true, returnByValue: true, timeout: 120000 });
  logs.push(`< ${JSON.stringify(r.result?.result?.value ?? r.result?.exceptionDetails?.exception?.description).slice(0, 2000)}`);
}
writeFileSync(`${out}.log`, logs.join('\n'));
ws.close();
proc.kill('SIGKILL');
process.exit(0);
